head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > setPlaceholder]<br/>SearchBox 컴포넌트의 placeholder 속성값을 변경합니다.",
    "validation" : [
        "placeholder(필수) 파라미터로 입력창에 placeholder 로 표시될 텍스트를 문자열로 설정합니다.",
        "placeholder 파라미터에 null 값을 설정하면 메소드가 실행되지 않습니다.",
        "기존 placeholder 와 동일한 값이면 변경하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (초기 placeholder = "old placeholder")
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        placeholder : "old placeholder",
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicSearchBox(cList);

    target1.setValue("");
};



// placeholder DOM 확인
scwin.btn_getPlaceholder_onclick = function (e) {
    let elem = document.querySelector("#" + target1.getID() + " input");

    if (elem) {
        wf_body_bottom.getObj("scwin").setReturnValue("placeholder : " + elem.getAttribute('placeholder'));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("target1 input element not found");
    }
};



// setPlaceholder 호출 - par_placeholder 값으로 placeholder 변경
scwin.btn_setPlaceholder_onclick = function (e) {
    let inputVal = par_placeholder.getValue();
    target1.setPlaceholder(inputVal);

    let elem = document.querySelector("#" + target1.getID() + " input");
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setPlaceholder('" + inputVal + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("placeholder : " + (elem ? elem.getAttribute('placeholder') : ''));
};



// setPlaceholder(null) 호출 - null 입력 시 메소드 미실행 검증
scwin.btn_setPlaceholderNull_onclick = function (e) {
    target1.setPlaceholder(null);

    let elem = document.querySelector("#" + target1.getID() + " input");
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setPlaceholder(null) 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("placeholder : " + (elem ? elem.getAttribute('placeholder') : ''));
};
